void until(const std::function<bool()>& ready){QElapsedTimer timer;timer.start();while(!ready()){if(timer.elapsed()>30000)throw std::runtime_error("Async test timeout");QTest::qWait(10);}QApplication::processEvents();}
struct Bytes {std::vector<uint8_t> v;void u8(unsigned x){v.push_back(uint8_t(x));}void u16(unsigned x){u8(x>>8);u8(x);}void u32(uint32_t x){u16(x>>16);u16(x);}void u64(uint64_t x){u32(uint32_t(x>>32));u32(uint32_t(x));}void length(uint64_t x,bool large){if(large)u64(x);else u32(uint32_t(x));}void raw(const std::vector<uint8_t>& x){v.insert(v.end(),x.begin(),x.end());}void raw(QByteArray x){v.insert(v.end(),x.begin(),x.end());}void four(const char* s){for(int i=0;i<4;++i)u8(unsigned(s[i]));}void string(const QString& s){u32(uint32_t(s.size()));for(auto c:s)u16(c.unicode());}void key(const char* s){QByteArray value(s);u32(uint32_t(value.size()));raw(value);}void f64(double value){u64(std::bit_cast<uint64_t>(value));}};
std::vector<uint8_t> channel(std::vector<uint8_t> pixels,int w,int h,int compression,bool large){Bytes b;b.u16(compression);if(compression==0)b.raw(pixels);else if(compression==1){for(int y=0;y<h;++y){if(large)b.u32(w+1);else b.u16(w+1);}for(int y=0;y<h;++y){b.u8(w-1);for(int x=0;x<w;++x)b.u8(pixels[size_t(y)*w+x]);}}else{if(compression==3)for(int y=0;y<h;++y)for(int x=w-1;x>0;--x)pixels[size_t(y)*w+x]=uint8_t(pixels[size_t(y)*w+x]-pixels[size_t(y)*w+x-1]);uLongf count=compressBound(uLong(pixels.size()));std::vector<uint8_t> zipped(count);require(compress2(zipped.data(),&count,pixels.data(),uLong(pixels.size()),9)==Z_OK,"Fixture ZIP failed");zipped.resize(count);b.raw(zipped);}return b.v;}
