QByteArray shapeExtra(){Bytes origin;origin.u32(1);origin.u32(16);origin.string("");origin.key("null");origin.u32(2);origin.key("keyOriginType");origin.four("long");origin.u32(1);origin.key("keyOriginShapeBBox");origin.four("Objc");origin.string("");origin.key("classFloatRect");origin.u32(4);for(auto [key,value]:{std::pair{"Left",0.},{"Top ",0.},{"Rght",4.},{"Btom",3.}}){origin.key(key);origin.four("UntF");origin.four("#Pxl");origin.f64(value);}Bytes fill;fill.u32(16);fill.string("");fill.key("RGBC");fill.u32(3);for(auto [key,value]:{std::pair{"Rd  ",200.},{"Grn ",80.},{"Bl  ",20.}}){fill.key(key);fill.four("doub");fill.f64(value);}return extraBlock("vogk",origin)+extraBlock("SoCo",fill);}
