void interchange(const QString& folder){FixtureLayer source;source.mask=true;source.extra=textExtra();auto imported=imaging::decodePhotoshop(psd(true,3,{source},320,120));auto before=imported.document;auto destination=std::filesystem::path((folder+"/editable.comp").toStdWString());ProjectStore store(makeWicProjectCodec());store.save(destination,before,before.layers[0].id);auto reopened=store.load(destination);require(reopened.readVersion==9&&reopened.document.layers[0].textJson==before.layers[0].textJson,"Imported editable text lost on project reopen");require(reopened.document.layers[0].mask&&reopened.document.layers[0].mask->placement==before.layers[0].mask->placement,"Imported mask placement lost");auto style=editing::decodeTextStyle(reopened.document.layers[0].textJson);style.content="Edited after reopen";reopened.document.layers[0]=editing::restyleText(reopened.document.layers[0],style);store.save(destination,reopened.document,reopened.document.layers[0].id);auto edited=store.load(destination);require(editing::decodeTextStyle(edited.document.layers[0].textJson).content==style.content,"Imported text cannot be edited after reopen");exportDocumentAtomic(edited.document,std::filesystem::path((folder+"/edited.png").toStdWString()));require(QFile::exists(folder+"/edited.png"),"Imported project export missing");}
