std::shared_ptr<const Raster> scene(){std::vector<uint8_t> bytes(64*48*4);for(int y=0;y<48;++y)for(int x=0;x<64;++x){auto i=size_t(y*64+x)*4;bytes[i]=uint8_t(x*3);bytes[i+1]=uint8_t(y*4);bytes[i+2]=uint8_t((x+y)*2);bytes[i+3]=255;if(x<16&&y<16){bytes[i]=200;bytes[i+1]=40;bytes[i+2]=30;}}return Raster::fromRgba(64,48,bytes.data(),64*4);}
void photoshop(){for(unsigned background:{0U,255U}){FixtureLayer mask;mask.mask=true;mask.maskInset=1;mask.maskWidth=2;mask.maskHeight=1;mask.maskDefault=uint8_t(background);mask.maskValue=uint8_t(255-background);auto imported=imaging::decodePhotoshop(psd(false,2,{mask}));const auto& layer=imported.document.layers[0];require(graphics::cachedMaskBackground(layer.mask->raster)==background,"PSD mask exterior default changed");const auto rendered=SoftwareRenderer().render(imported.document,0,0,4,3);require(rendered->pixel(0,0).a==(background?layer.raster->pixel(0,0).a:0),"PSD exterior concealed or exposed image outside authored mask");require(rendered->pixel(1,1).a==(background?0:layer.raster->pixel(1,1).a),"PSD authored center mask changed");}FixtureLayer additive;additive.blend="lddg";require(imaging::decodePhotoshop(psd(false,0,{additive})).document.layers[0].blend==Blend::LinearDodge,"PSD additive blend lost");FixtureLayer budgetMask;budgetMask.mask=true;imaging::ImportOptions maskLimit;maskLimit.remainingMaskPixels=40;rejects([&]{imaging::decodePhotoshop(psd(false,0,{budgetMask,budgetMask}),maskLimit);},"PSD aggregate mask budget was checked too late");imaging::ImportOptions working;working.maxWorkingBytes=100;rejects([&]{imaging::decodePhotoshop(psd(false,0,{budgetMask}),working);},"PSD combined working budget ignored");for(bool large:{false,true})for(int compression=0;compression<4;++compression){auto merged=imaging::decodePhotoshop(flattened(large,compression));require(merged.document.layers[0].raster->pixel(0,0)==Pixel{40,90,140,255},"Flattened Photoshop decode mismatch");}FixtureLayer liveShape;liveShape.extra=shapeExtra();auto shape=imaging::decodePhotoshop(psd(false,0,{liveShape}));require(!shape.document.layers[0].shapeJson.empty()&&shape.document.layers[0].raster->pixel(1,1).r==200,"PSD editable shape conversion");QTemporaryDir interchangeFolder;interchange(interchangeFolder.path());for(bool large:{false,true})for(int compression=0;compression<4;++compression){FixtureLayer source;source.mask=true;auto decoded=imaging::decodePhotoshop(psd(large,compression,{source}));require(decoded.document.layers.size()==1,"Layer count");const auto& l=decoded.document.layers[0];require(l.raster&&l.mask&&l.raster->pixel(0,0)==Pixel{28,55,83,128},"PSD decoded premultiplication");require(l.mask->raster->pixel(1,1)==128&&l.mask->placement.has_value(),"PSD mask placement");}FixtureLayer divider;divider.w=divider.h=0;divider.section=3;FixtureLayer base;base.name="Base";FixtureLayer clipped=base;clipped.name="Clipped";clipped.clipping=true;FixtureLayer group=divider;group.name="Folder";group.section=1;group.opacity=128;auto d=imaging::decodePhotoshop(psd(false,0,{divider,base,clipped,group}));require(d.document.layers.size()==3,"PSD folders");require(d.document.layers[0].parentId==d.document.layers[2].id&&d.document.layers[1].maskSourceId==d.document.layers[0].id,"PSD parent/clipping");require(std::abs(d.document.layers[2].opacity-128/255.)<1e-8,"PSD folder opacity");FixtureLayer text;text.extra=textExtra();auto t=imaging::decodePhotoshop(psd(false,0,{text}));auto style=editing::decodeTextStyle(t.document.layers[0].textJson);require(style.content==QString::fromUtf8("Editable \xf0\x9f\x8c\x8e\n")&&style.fontSize==18&&std::abs(style.red-.7)<1e-8,"PSD editable text metadata");auto bad=psd(false,0);bad.resize(35);rejects([&]{imaging::decodePhotoshop(bad);},"Truncated PSD accepted");bad=psd(false,0);bad[23]=16;rejects([&]{imaging::decodePhotoshop(bad);},"16-bit PSD accepted");imaging::ImportOptions options;options.remainingPixels=12;FixtureLayer wide;wide.x=-4;wide.w=12;auto crop=imaging::decodePhotoshop(psd(false,3,{wide}),options);require(crop.document.layers[0].raster->width==4&&!crop.conversions.empty(),"Oversized PSD layer not cropped");options.cancelled=[] {return true;};rejects([&]{imaging::decodePhotoshop(psd(false,0),options);},"PSD cancellation ignored");}
void camera(){auto source=scene();effects::CameraRawSettings neutral;require(effects::applyCameraRaw(*source,neutral)->rgba()==source->rgba(),"Camera Raw identity changed pixels");for(auto [key,value]:{std::pair{"exposure",1.},{"temperature",45.},{"clarity",50.},{"curveDarks",40.},{"redHue",60.},{"gradeGlobalSaturation",30.},{"sharpenAmount",100.},{"opticsVignette",50.},{"vertical",45.},{"primaryRedHue",50.}}){auto s=neutral;s.set(key,value);auto out=effects::applyCameraRaw(*source,s);require(out->rgba()!=source->rgba(),key);require(out->width==source->width&&out->height==source->height,"Camera dimensions changed");for(auto p:out->tiles[0]->pixels)require(p.r<=p.a&&p.g<=p.a&&p.b<=p.a,"Premultiplication violated");}auto settings=neutral;settings.curves[0]={{0,0},{128,185},{255,255}};settings.points.push_back({20,.7,.4,30,20,0,40,.5,.5});settings.guides.push_back({{.1,.2},{.9,.25}});auto roundtrip=effects::decodeCameraRawSettings(effects::encodeCameraRawSettings(settings));require(effects::encodeCameraRawSettings(roundtrip)==effects::encodeCameraRawSettings(settings),"Camera settings lost on save");require(effects::applyCameraRaw(*source,settings)->rgba()!=source->rgba(),"Curve and point color ignored");rejects([&]{effects::applyCameraRaw(*source,settings,1,{},[]{return true;});},"Camera cancellation ignored");auto collapsed=neutral;collapsed.set("scale",-100);require(effects::applyCameraRaw(*source,collapsed)->pixel(32,24).a==0,"Collapsed geometry returned original image");auto invalid=settings;invalid.values["exposure"]=6;rejects([&]{effects::applyCameraRaw(*source,invalid);},"Invalid Camera exposure accepted");require(effects::cameraRawWhiteBalance(*Raster::filled(8,8,{180,100,70,255})).has_value(),"Auto white balance failed");}
